  ('public.verify_collection_worker_cron_secret(text)','8e49a92b4715911882059cb5aaa959b3b31ca43dd4db26ad34f4b4c1377cd86d'),
  ('public.verify_report_cron_secret(text)','2485365d31354bf617074faef576e14c1987db90e9135c155fe907ad3d6b6ba9')
), compared AS (
  SELECT e.identity,e.definition_sha256,
    CASE WHEN p.oid IS NOT NULL THEN encode(sha256(convert_to(pg_catalog.pg_get_functiondef(p.oid),'UTF8')),'hex') END actual_sha256
  FROM expected e LEFT JOIN pg_catalog.pg_proc p ON p.oid=pg_catalog.to_regprocedure(e.identity)
)
SELECT clock_timestamp() captured_at,
  count(*) expected_routines,
  count(*) FILTER(WHERE actual_sha256 IS NULL) missing_routines,
  count(*) FILTER(WHERE actual_sha256 IS NOT NULL AND actual_sha256<>definition_sha256) changed_routines,
  coalesce(jsonb_agg(jsonb_build_object('identity',identity,'expected_sha256',definition_sha256,'actual_sha256',actual_sha256) ORDER BY identity) FILTER(WHERE actual_sha256 IS DISTINCT FROM definition_sha256),'[]'::jsonb) differences
FROM compared;
COMMIT;
